                        p1 = (cx + R * math.cos(math.radians(angles[i])), cy + R * math.sin(math.radians(angles[i])))
                        p2 = (cx + R * math.cos(math.radians(angles[(i+1)%6])), cy + R * math.sin(math.radians(angles[(i+1)%6])))
                        edges.append((p1, p2, (dr, dc)))
