        elif self.grid_type == "tri":
            s = R * math.sqrt(3)
            return (self.grid.columns + 1) * (s/2), self.grid.rows * 1.5 * R + 0.5 * R
        elif self.grid_type == "polar":
            rw = R * 1.5; max_r = (rw * 2) + self.grid.rows * rw
