    arcade.draw_rect_filled(arcade.LBWH(0, 0, config.SCREEN_WIDTH, config.SCREEN_HEIGHT), overlay_color); cw, ch = config.SCREEN_WIDTH/2, config.SCREEN_HEIGHT/2
